// Verify x-zekerflex-signature: v1=HMAC_SHA256(secret, `${timestamp}.${body}`)
const crypto = require('crypto');
const secret = $env.ZEKERFLEX_WEBHOOK_SECRET;
const out = [];
for (const item of $input.all()) {
  const h = item.json.headers || {};
  const body = JSON.stringify(item.json.body);
  if (secret) {
    const expected = 'v1=' + crypto.createHmac('sha256', secret).update(`${h['x-zekerflex-timestamp']}.${body}`).digest('hex');
    if (expected !== h['x-zekerflex-signature']) throw new Error('Ongeldige ZekerFlex-handtekening');
  }
  out.push({ json: { type: item.json.body.type, data: item.json.body.data } });
}
return out;
